			ItemProperties.register(ERIDIUM_HEART.get(), new ResourceLocation("truedarkness:eridium_heart_type"), (itemStackToRender, clientWorld, entity, itemEntityId) -> (float) BlinkEridium2ZnachieniieSvoistvaProcedure.execute(entity));
